export function getAllSpriteUrls() {
  return Object.keys(SPRITE_REGISTRY).map((name) => `/sprites/${name}`);
}

export function getAircraftSpriteUrls() {
  return Object.entries(SPRITE_REGISTRY)
    .filter(([, r]) => r.category === 'aircraft')
    .map(([name]) => `/sprites/${name}`);
}

export function getVesselSpriteUrls() {
  return Object.entries(SPRITE_REGISTRY)
    .filter(([, r]) => r.category === 'vessel')
    .map(([name]) => `/sprites/${name}`);
}

export function getGroundSpriteUrls() {
  return Object.entries(SPRITE_REGISTRY)
    .filter(([, r]) => r.category === 'ground')
    .map(([name]) => `/sprites/${name}`);
}
